import { test, expect } from '@playwright/test';

test('R4 save shows a success confirmation', async ({ page }) => {
  await page.goto('https://anupsahoo.github.io/progress-agent/customer-maint');
  await page.getByLabel('Customer number').fill('1');
  await page.getByRole('button', { name: 'Look up' }).click();
  await page.getByLabel('City').fill('Cambridge');
  await page.getByRole('button', { name: 'Save' }).click();
  await expect(page.getByRole('status')).toHaveText('Record updated successfully.');
});
